We have,

\begin{aligned}
\lim _{x \rightarrow 1} & \frac{\tan \left(x^{2}-1\right)}{x-1} \\
&=\lim _{x \rightarrow 1} \frac{\sec ^{2}\left(x^{2}-1\right) \cdot 2 x}{1} \quad \text { [using L'Hospital Rule] } \\
&=2 \sec ^{2} 0=2
\end{aligned}

We have,

\begin{aligned}
\lim _{n \rightarrow \infty} \frac{\left(1^{2}+2^{2}+\ldots+n^{2}\right) \sqrt[n]{n}}{(n+1)(n+10)(n+100)} \\
=& \lim _{n \rightarrow \infty} \frac{n(n+1)(2 n+n)}{6(n+1)(n+10)(n+100)}\left(\lim _{n \rightarrow \infty} \sqrt[n]{n}\right) \\
=& \lim _{n \rightarrow \infty} \frac{2 n^{2}+n}{6(n+10)(n+100)} \\
=& \lim _{n \rightarrow \infty} \frac{2+\frac{1}{n}}{6\left(1+\frac{10}{n}\right)\left(1+\frac{100}{n}\right)} \\
=& \frac{2+0}{6(1+0)(1+0)} \\
=& \frac{2}{6}=\frac{1}{3}
\end{aligned}

We have, $\lim _{x \rightarrow \infty}\left(\sqrt{a^{2} x^{2}+b x+x}-a x\right)$
\begin{aligned}
&=\lim _{x \rightarrow \infty}\left(\left(\sqrt{a^{2} x^{2}+b x+x}-a x\right) \times \frac{\left(\sqrt{a^{2} x^{2}+b x+x}+a x\right)}{\left(\sqrt{a^{2} x^{2}+b x}+x+a x\right)}\right) \\
&=\lim _{x \rightarrow \infty}\left(\frac{\left(a^{2} x^{2}+b x+x\right)-a^{2} x^{2}}{x\left\{\sqrt{a^{2}+\frac{b}{x}+\frac{1}{x}}+a\right\}}\right) \\
&=\lim _{x \rightarrow \infty}\left(\frac{(b+1) x}{x\left\{\sqrt{a^{2}+\frac{b}{x}+\frac{1}{x}}+a\right\}}\right)=\frac{b+1}{2 a}
\end{aligned}

We have,

\begin{aligned}
&\lim _{\theta \rightarrow \frac{\pi}{2}} \frac{\frac{\pi}{2}-\theta}{\cot \theta}=\lim _{\theta \rightarrow \frac{\pi}{2}} \frac{-1}{-\operatorname{cosec}^{2} \theta} \text { [usingL'Hospital Rule] } \\
&\Rightarrow \lim _{\theta \rightarrow \frac{\pi}{2}} \sin ^{2} \theta=\sin ^{2} \frac{\pi}{2}=1
\end{aligned}
